// ***************
// Filename: i2c_master_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of i2c_master: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to i2c_master's logic on named ports, its
//   status comes back on input ports. I2C master: transaction control, target
//   address, length, SCL divider and status. Generated by
//   ip/scripts/regmap_gen.py from i2c_master_regs.json: edit the JSON and
//   regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "I2CM" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CTRL        CMD  transaction control; reads EN / READ / NO_STOP as
//                       stored, START reads 0
//                       [0] EN: 1: master enabled
//                       [1] START: write 1: start the transaction (a command,
//                         reads 0)
//                       [2] READ: 1: read, 0: write (bytes from the AXI-
//                         Stream slave)
//                       [3] NO_STOP: 1: no STOP at the end (repeated START
//                         next)
//     0x14 ADDR        RW   7-bit target address, reset 0x0
//     0x18 LEN         RW   bytes to transfer, reset 0x0
//     0x1C DIV         RW   phase clocks - 1: f_scl = f_clk / (4 * (DIV +
//                       1)), reset DIV_RST
//     0x20 STATUS      CMD  status; write 1s to [3:1] to clear those flags
//                       [0] BUSY: transaction in progress
//                       [1] DONE: transaction finished (W1C; also cleared by
//                         START)
//                       [2] NACK: target did not acknowledge (W1C)
//                       [3] ARB_LOST: arbitration lost (W1C)
//                       [31:16] RX_LEVEL: bytes in the receive FIFO
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-16
module i2c_master_regs #(
  parameter int DIV_RST = 249  // DIV at reset (CLK_HZ / (4 * SCL_HZ) - 1)
) (
  input  logic          aclk,           // clock
  input  logic          aresetn,        // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // r: i2c_master_regs_if.regs (src/include/i2c_master_regs_if.sv) {ctrl_i=sts_ctrl ctrl_o=cfg_ctrl ctrl_wr_o=cfg_ctrl_wr addr_o=cfg_addr addr_wr_o=cfg_addr_wr len_o=cfg_len len_wr_o=cfg_len_wr div_o=cfg_div div_wr_o=cfg_div_wr status_i=sts_status status_o=cfg_status status_wr_o=cfg_status_wr}
  i2c_master_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [4-1:0] ctrl_i;
  logic [4-1:0] ctrl_o;
  logic ctrl_wr_o;
  logic [7-1:0] addr_o;
  logic addr_wr_o;
  logic [16-1:0] len_o;
  logic len_wr_o;
  logic [16-1:0] div_o;
  logic div_wr_o;
  logic [32-1:0] status_i;
  logic [32-1:0] status_o;
  logic status_wr_o;
  assign ctrl_i = r.sts_ctrl;
  assign r.cfg_ctrl = ctrl_o;
  assign r.cfg_ctrl_wr = ctrl_wr_o;
  assign r.cfg_addr = addr_o;
  assign r.cfg_addr_wr = addr_wr_o;
  assign r.cfg_len = len_o;
  assign r.cfg_len_wr = len_wr_o;
  assign r.cfg_div = div_o;
  assign r.cfg_div_wr = div_wr_o;
  assign status_i = r.sts_status;
  assign r.cfg_status = status_o;
  assign r.cfg_status_wr = status_wr_o;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "I2CM";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h10;
  localparam logic [7:0] A_ADDR = 8'h14;
  localparam logic [7:0] A_LEN = 8'h18;
  localparam logic [7:0] A_DIV = 8'h1C;
  localparam logic [7:0] A_STATUS = 8'h20;
  localparam int MAP_WORDS = 9;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(8)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] addr_q;
  logic [31:0] len_q;
  logic [31:0] div_q;
  logic [31:0] status_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      ctrl_q <= '0;
      ctrl_wr_o <= 1'b0;
      addr_q <= 32'h0;
      addr_wr_o <= 1'b0;
      len_q <= 32'h0;
      len_wr_o <= 1'b0;
      div_q <= 32'(DIV_RST);
      div_wr_o <= 1'b0;
      status_q <= '0;
      status_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        addr_wr_o <= wr_en && wa == A_ADDR;
        if (wr_en && wa == A_ADDR) addr_q <= (addr_q & ~wmask) | (wr_data & wmask);
      end
      begin
        len_wr_o <= wr_en && wa == A_LEN;
        if (wr_en && wa == A_LEN) len_q <= (len_q & ~wmask) | (wr_data & wmask);
      end
      begin
        div_wr_o <= wr_en && wa == A_DIV;
        if (wr_en && wa == A_DIV) div_q <= (div_q & ~wmask) | (wr_data & wmask);
      end
      begin
        status_wr_o <= wr_en && wa == A_STATUS;
        if (wr_en && wa == A_STATUS) status_q <= (status_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[4-1:0];
  assign addr_o = addr_q[7-1:0];
  assign len_o = len_q[16-1:0];
  assign div_o = div_q[16-1:0];
  assign status_o = status_q[32-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CTRL: rd_data = 32'(ctrl_i);
      A_ADDR: rd_data = addr_q;
      A_LEN: rd_data = len_q;
      A_DIV: rd_data = div_q;
      A_STATUS: rd_data = 32'(status_i);
      default: begin
      end
    endcase
  end
endmodule
